def transform(grid):
    pts={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v: pts.setdefault(v,[]).append((r,c))
    if not pts: return [row[:] for row in grid]
    boxes={v:(min(r for r,c in p),max(r for r,c in p),min(c for r,c in p),max(c for r,c in p)) for v,p in pts.items()}
    frame=max(pts,key=lambda v:len(pts[v]))
    a,b,c,d=boxes[frame]
    keep=set()
    for v,(e,f,g,h) in boxes.items():
        if v!=frame and a<=e and f<=b and c<=g and h<=d: keep.add(v)
    return [[v if v in keep else 0 for v in row] for row in grid]

